def ref(n):return {'$ref':'#/$defs/'+n}
def obj(**p):return {'type':'object','properties':p,'required':list(p),'additionalProperties':False}
def arr(t,n):return {'type':'array','items':t,'maxItems':n}
def const(v):return {'const':v}
def enum(*v):return {'enum':list(v)}
def integer(a,b):return {'type':'integer','minimum':a,'maximum':b}
def null(t):return {'anyOf':[t,{'type':'null'}]}
def record(n,profile,**p):D[n]=obj(profile=const(profile),**p)
