for k,i in [('retire','RetirementRequestIntent'),('restore','RestorationRequestIntent'),('purge','PurgeIntent'),('hold-add','HoldIntent'),('hold-remove','HoldIntent'),('policy-update','PolicyIntent'),('dependency-satisfy','DependencyIntent'),('publication-anchor','AnchorIntent')]:
 n='Request-'+k;record(n,'umf.table-recovery-request/0.1',requestId=UUID,kind=const(k),providerId=UUID,storeId=UUID,installationId=S,targetCustody=ref('TargetCustody'),purpose=enum('production','native-acceptance'),contextDigest=H,archiveId=UUID,lineageId=UUID,tableToken=UUID,physicalGeneration=UUID,table=S,record=ref('Ref'),planBinding=ref('PlanBinding') if k in ('retire','restore') else {'type':'null'},lifecycleBinding={'type':'null'} if k=='retire' else ref('LifecycleBinding'),intent=ref(i),executionPolicyDigest=H,componentPolicyDigest=H,providerDefinitionDigest=H);requestbranches.append(ref(n))
