roots=['ExecutionPolicy','DataConfig','DataContext','DataApproval','ClockContext','ClockCheckpoint','Dependency','TableIntent','TableArchiveRef','TableArchiveSources','Lineage','LineageObservation','Carrier','WholeArchive','Header','PrivateProof','Lifecycle','Reservation','PublicReceipt','Event','Outcome','Result','Permit','ClockEnvelope','RecoveryRequest','ProgramRef']
schema={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:umf:proposed:g10-r2-records:001','title':'PROPOSED R2 new closed record syntactic layer; NO authority/native verifier','description':'Relational equality/state/count/UTF8 byte/canonical/signature/custody/receipt/version adaptation invariants in contract/provider/lifecycle/cross-carrier/wire-adaptations are additionally mandatory. This schema neither issues capabilities nor parses old programs/plans as new versions.','oneOf':[ref(n) for n in roots],'$defs':D}
